insert into public.eoc_assessment_items (id,section,section_sort,item_no,item_text,applies_primary,applies_alternate,iat_links) values
('dad6efac-59fd-54ab-9189-443057bce2f2'::uuid,'Hazard and Vulnerability Assessment',1,1,'The EOC can survive the effects of relevant hazards as identified in jurisdictional hazard and vulnerability assessment).',true,false,'{B2.1,B2.2}'::text[]),('e3257a01-d733-5761-a0aa-4c1e5e3d65ce'::uuid,'Hazard and Vulnerability Assessment',1,2,'The EOC Operations Manual identifies a staff position that is tasked with identifying such vulnerabilities.',true,false,'{B7.1,B4.1}'::text[]),('466c6b65-c276-5594-b038-20b6bc1ad3d4'::uuid,'Hazard and Vulnerability Assessment',1,3,'EOC plans and procedures specifically address the potential impacts of natural, accidental, and intentional risks to the EOC or alternate facility.',true,false,'{B2.7,B7.1}'::text[]),('bae8e7b7-aa10-5295-819b-fc7ff24673c9'::uuid,'Personnel Requirements',2,1,'The EOC has adequate staffing based on sustained operations (i.e., minimum—72 hours, three-deep roster for each position).',true,false,'{B4.2,B4.3}'::text[]),('2578c1cb-43f5-54f5-b3de-318cf6ada8da'::uuid,'Personnel Requirements',2,2,'The EOC has a system in place to manage volunteers.',true,false,'{B6.4}'::text[]),('538e0bbf-15fd-5e7b-bddb-776d1e7b1446'::uuid,'Personnel Requirements',2,3,'Personnel are identified to operate and maintain communications equipment at the EOC during an emergency event.',true,false,'{B4.2,B7.2}'::text[]),('be32d702-6cd8-5fbd-8a66-a016d2c8d69c'::uuid,'Personnel Requirements',2,4,'Personnel (e.g., EOC personnel, police, or other security personnel) are identified to provide security to the facility in the event of an emergency.',true,false,'{B2.6}'::text[]),('56c9fef6-5c58-5038-8966-991ba757fddc'::uuid,'Personnel Requirements',2,5,'A safety or security agent is identified to issue access control badges and authorize access to EOC personnel from other jurisdictions, including Regional and National personnel.',true,false,'{B2.6}'::text[]),('cbb724d3-71ec-577b-8d65-5bc9c39f36ca'::uuid,'Personnel Requirements',2,6,'Additional government personnel are readily available to augment the EOC should the emergency escalate beyond the capability of the on-duty EOC team.',true,false,'{B4.2,B6.6}'::text[]),('95f42c2a-1b0e-58d5-8c2f-f070b61e8329'::uuid,'Personnel Requirements',2,7,'The emergency monitoring and warning system(e.g. water level measurements) is identified and is monitored and/or staffed 24 hours, seven days a week.',true,false,'{B5.6,B4.3}'::text[]),('660604cf-0b2f-5bf7-ba33-01b795a63e33'::uuid,'Plans',3,1,'An EOC Operations and Administration/Functional Manual is developed and maintained.',true,false,'{B7.1,B1.4}'::text[]),('49ddcf23-c0f8-53a1-9247-9ee4a0263455'::uuid,'Plans',3,2,'EOC plans and procedures identify specific communications channels to local agencies and organizations that are assigned emergency responsibilities.',true,false,'{B3.4}'::text[]),('9f45f04f-1584-534b-b06e-5014303a8663'::uuid,'Plans',3,3,'EOC plans and procedures specifically address the potential impacts of relevant risks to the EOC or alternate facility.',true,false,'{B2.7,B7.1}'::text[]),('75c19d7f-b021-58e7-9ca4-c1039dcb15d5'::uuid,'Plans',3,4,'EOC plans and procedures address the protection of computers, communications equipment, and other vital EOC equipment in a hazard event.',true,false,'{B2.2,B2.7}'::text[]),('18919b92-6763-5550-bff7-d07a5d5b1d81'::uuid,'Plans',3,5,'Plans and procedures are in place to supplement EOC personnel, including identifying backup personnel to facilitate 24-hour operations.',true,false,'{B4.2,B4.3}'::text[]),('c75ea658-3b10-5a61-8dab-4e1631374b7c'::uuid,'Plans',3,6,'Plans and procedures are in place to test the generator at full load on a regular basis.',true,false,'{B2.3}'::text[]),('d51c49e6-343c-572e-87bb-ade0e0337414'::uuid,'Plans',3,7,'Fuel contracts are in place to ensure regular delivery of fuel to the EOC during a long-term event.',true,false,'{B2.3}'::text[]),('889115b4-1e80-59ae-b209-2119d3de51b9'::uuid,'Plans',3,8,'Resource inventories are developed and kept up-to-date.',true,false,'{B6.3}'::text[]),('84f8a277-8b37-5058-9b76-0842a9b560d5'::uuid,'Plans',3,9,'EOC has the capability to coordinate voluntary organizations during disasters.',true,false,'{B6.4}'::text[]),('abd661fd-8fb1-5927-9d81-81786c971646'::uuid,'Plans',3,10,'The EOC has developed Public Service ContinuityPlan in the event of disaster/disruption.',true,false,'{B2.7}'::text[]),('191c4556-abf9-5183-b5ae-24aade6d6246'::uuid,'Plans',3,11,'The EOC has the ability to obtain pre-disaster maps, photographs, and other documents.',true,false,'{B5.3}'::text[]),('ab4d146a-c869-5f0c-80d1-fb7b208a906c'::uuid,'Plans',3,12,'The conditions and process under which the EOC is activated, staffed, and deactivated are defined.',true,false,'{B1.2,B1.3}'::text[]),('670d520a-8d49-51d3-b5bd-661dad54f67e'::uuid,'Plans',3,13,'Warning and Public Information dissemination agreements are in place with local radio, TV, cable TV, newspapers, and other media.',true,false,'{B3.4}'::text[]),('dafc32ee-e6e4-59b1-8a62-03cf3a0f7bad'::uuid,'Plans',3,14,'The EOC has established alternate methods for contacting media.',true,false,'{B3.1,B3.4}'::text[]),('b83af987-2596-5592-871b-300bac170959'::uuid,'Plans',3,15,'Mutual Aid Agreements/Memorandums of Understanding (MOUs)/Twinning Concept/System are in place with other EOCs to obtain trained personnel for augmentation.',true,false,'{B6.6,B1.5}'::text[]),('18a0c76d-105b-5e56-bfb6-5d5127b991f6'::uuid,'Plans',3,16,'Security measures are addressed in EOC plans and procedures.',true,false,'{B2.6}'::text[]),('b8a19d03-7c28-5fbb-b997-45c04bbf479d'::uuid,'Plans',3,17,'Security plans address actions associated with higher threat levels (e.g., additional barriers, increased surveillance, additional guards).',true,false,'{B2.6}'::text[]),('5241065a-c862-58c6-861d-421c95af0f81'::uuid,'Plans',3,18,'Plans address scaled EOC activation and operations depending on the scope of the emergency.',true,false,'{B1.2,B1.3}'::text[]),('0a60623b-3a31-5dc3-891a-dee34d854f7d'::uuid,'Site Selection',4,1,'The EOC is in a government owned, privately owned /leased facility.',true,false,'{}'::text[]),('e380d90a-7265-5d32-8ceb-a618f4223fdf'::uuid,'Site Selection',4,2,'The EOC is in an area that avoids congestion (e.g., transportation chokepoints such as inadequate thoroughfares and bridges) or debris from collapsing buildings.',true,false,'{B2.1}'::text[]),('539489b7-46d6-550b-b68e-410429489def'::uuid,'Site Selection',4,3,'The EOC is located near an adequate road network for ease of access.',true,false,'{B2.1}'::text[]),('41f0241f-ed1e-5f32-a0a7-4e92a60c85bb'::uuid,'Site Selection',4,4,'Government executives/key officials have rapid access to the EOC.',true,false,'{B2.1}'::text[]),('8680eb08-ba3c-5538-91b4-86e08860b072'::uuid,'Site Selection',4,5,'The EOC has adequateparking for activations.',true,false,'{B2.4}'::text[]),('1c658878-42f0-520c-8859-9dffaf3e803e'::uuid,'Site Selection',4,6,'The EOC is located outside known high-risk areas (e.g., floods, earthquakes, nuclear power plant, and Hazardous Material (HAZMAT) sites).',true,false,'{B2.1}'::text[]),('1692c16f-8bea-5b37-b000-896e9c53d244'::uuid,'Site Selection',4,7,'If the EOC is located within a known high-risk area, actions have been taken to mitigate risk.',true,false,'{B2.1}'::text[]),('0cf32d0b-5599-5d58-aed8-f6a6e6a61a94'::uuid,'Site Selection',4,8,'If necessary, the EOC is located away from airfields and airports.',true,false,'{B2.1}'::text[]),('6e7d1932-9406-5ef7-bddd-8e892b3a8553'::uuid,'Site Selection',4,9,'The EOC is located away from high-voltage power lines and pipelines.',true,false,'{B2.1}'::text[]),('14187f64-bb3e-5ddf-aaff-8e275f2ed591'::uuid,'Site Selection',4,10,'The EOC is situated at a location that allows good radio transmission and reception.',true,false,'{B3.1,B3.2}'::text[]),('d55081a5-21c0-56f2-830c-e7d8251e7475'::uuid,'Site Selection',4,11,'With respect to seismic safety, the EOC conforms to theNational Building Code of the Philippines (for revision and development).',true,false,'{B2.2}'::text[]),('522cae7e-fe5a-511a-a555-08ad95102798'::uuid,'Site Selection',4,12,'The EOC site has a helicopter landing pad/zone or a nearby area clear enough for a helicopter to approach/land.',true,false,'{}'::text[]),('c2d128d5-a09b-594d-b119-602784381850'::uuid,'Site Selection',4,13,'The EOC site can accommodate long-term growth.',true,false,'{B2.4}'::text[]),('169c55a7-9a93-5800-9d5b-f6972110bef5'::uuid,'Site Selection',4,14,'Construction of the EOC does not change or alter listed, or nationally-designated, historic sites or structures.',true,false,'{}'::text[]),('91460b56-f3ad-53a3-9928-9fcd2fa08d6c'::uuid,'Mitigation Considerations',5,1,'Actions have been taken to mitigate against known relevant risks from natural, accidental, intentional, and human-induced hazards—as identified by jurisdictional hazard and vulnerability assessments.',true,false,'{B2.1}'::text[]),('b671f51b-b842-5ff1-a2cf-41bce329e64a'::uuid,'Mitigation Considerations',5,2,'The EOC has a collective protection system for Chemical, Biological, Radiological, Nuclear, and Explosion(CBRNE) agents.',true,false,'{}'::text[]),('c7274771-11af-591f-9bf5-5055d2562d2b'::uuid,'Mitigation Considerations',5,3,'The lowest floor of the EOC is elevated above any flooding and other identified hazards in the jurisdiction’s hazard and vulnerability assessment.',true,false,'{B2.1}'::text[]),('8910f1d1-77e9-513a-81bc-6fe0bb1d99f7'::uuid,'Mitigation Considerations',5,4,'EOC is retrofitted to be resilient to seismological hazards',true,false,'{B2.2}'::text[]),('f078a8b7-03b3-54a7-b2f4-3287031abab1'::uuid,'Mitigation Considerations',5,5,'The conditions that would cause the EOC to be relocated have been identified.',true,false,'{B2.7}'::text[]),('fe4d05df-224a-54ee-b148-f25f847e0b96'::uuid,'Building Design',6,1,'The design/construction of the EOCin adherence of the National Building Code is appropriate for the relevant risks identified for the jurisdiction.',true,false,'{B2.2}'::text[]),('727b2600-7e55-522a-acea-47221d5ac3a5'::uuid,'Building Design',6,2,'The EOC has the special structural capabilities necessary to improve its survivability/resiliency.',true,false,'{B2.2}'::text[]),('1e028b13-ad14-540d-86a1-ac9371c3d105'::uuid,'Building Design',6,3,'The EOC has protection from blast effects.',true,false,'{B2.2}'::text[]),('84802648-e409-5bd4-bbbd-ebd01085e4b7'::uuid,'Building Design',6,4,'The EOC has built in fire protection and other safety devices (e.g., sprinklers).',true,false,'{B2.2}'::text[]),('dbf497ff-7f49-5149-a76d-3102f74defc5'::uuid,'Building Design',6,5,'A filtration system to protect personnel from chemical contamination and air-borne pathogenshas been installed for EOCs that are vulnerable to Chemical, Biological, Radiological, Nuclearand Explosive (CBRNE) agentsas indicated by the jurisdiction’s hazard and vulnerability assessment.',true,false,'{}'::text[]),('889a9840-c385-5f96-abe6-6cb32ec8decb'::uuid,'Building Design',6,6,'Wiring and cabling of the EOC facility is designed to accommodate future expansion.',true,false,'{B2.4}'::text[]),('ad7a857d-85cd-5dec-95c3-6f2b93c42a9b'::uuid,'Building Design',6,7,'The EOC complies with requirements of Persons with Disabilities(PwD).',true,false,'{B2.2}'::text[]),('c3b11f1e-47ff-5bab-9758-23832e4f351a'::uuid,'Building Design',6,8,'EOC design and landscaping blends in with the local community.',true,false,'{}'::text[]),('76294f27-9fab-5a55-b8c2-2942aaa2f701'::uuid,'Physical Security',7,1,'The building housing the EOC is set back from tree lines.',true,false,'{B2.6}'::text[]),('5d4bc472-f4b7-59b2-8f0f-d9fd8e6c718e'::uuid,'Physical Security',7,2,'Physical security measures (e.g., barriers and gates) are used to restrict vehicle access to the EOC.',true,false,'{B2.6}'::text[]),('d9d3205e-021d-52f0-bad5-9711841abcab'::uuid,'Physical Security',7,3,'The EOC is located in an area where it can quickly be secured.',true,false,'{B2.6}'::text[]),('0cf81ad4-9d1a-52bc-bbcc-39150336bc4a'::uuid,'Physical Security',7,4,'Access to the EOC is controlled by a badge, card-swipe, and/or biometric system. The security system in use is adequate to control access to the facility and within the facility.',true,false,'{B2.6}'::text[]),('f7f6bf06-16d2-59d9-a790-300ad382eaac'::uuid,'Physical Security',7,5,'There are no access control systems (i.e., card access, elevators, or lockout stairwells) that could preclude access to or egress from the facility if rendered non-operational.',true,false,'{B2.6}'::text[]),('473ebbb9-2302-5e1b-ad56-173d6eca434d'::uuid,'Physical Security',7,6,'If the building shares access with another organization, processes are in place to restrict access to operational areas when appropriate.',true,false,'{B2.6}'::text[]),('d1d772e6-e4f6-5601-bdf9-f0e4e5379632'::uuid,'Physical Security',7,7,'Consideration of security measures and implementation to secure parking areas.',true,false,'{B2.6}'::text[]),('aab59fa2-a30c-5aad-a8cc-625ec13a89cf'::uuid,'Physical Security',7,8,'Consideration, if appropriate, to provide Closed Circuit Television (CCTV) monitoring at all angles in case of possible security breach.',true,false,'{B2.6,B3.6}'::text[]),('6eb3f5f5-a239-5678-a46a-9a690c42c3fa'::uuid,'Physical Security',7,9,'Adequate lighting is provided both inside and outside the EOC.',true,false,'{B2.6}'::text[]),('f759a611-ad9b-5e79-9bca-a510d9c6e544'::uuid,'Physical Security',7,10,'Appropriate security measures have been considered and taken to ensure safety of items received.',true,false,'{B2.6}'::text[]),('275ac17f-8daa-598d-bf2b-55278a812aca'::uuid,'Physical Security',7,11,'Consideration of security measures and implementationto control access to the facility.',true,false,'{B2.6}'::text[]),('68c86e60-47fb-5617-9e8c-db887a641040'::uuid,'Physical Security',7,12,'Access is restricted to control panels of critical systems.',true,false,'{B2.6}'::text[]),('bc778507-9d2c-583c-8a59-230b7e458cfd'::uuid,'Physical Security',7,13,'Ventilation, and air-conditioning (VAC) systems are available and controllable 24-hours a day, seven days a week.',true,false,'{B2.4}'::text[]),('fd86ca4d-867b-55af-b80c-216e3ef6105b'::uuid,'Physical Security',7,14,'Appropriate/authorized staff has 24-hour access to the facility.',true,false,'{B2.6}'::text[]),('d540d4aa-b5ea-5033-8708-5047f45124ff'::uuid,'Physical Security',7,15,'Periodic inspection of all personnel, equipment, and systems.',true,false,'{B7.6}'::text[]),('422e77e0-a327-559f-9c81-ffe83e85b340'::uuid,'Room Design',8,1,'If EOC space is not dedicated, plans are in place to relocate day staff to another location to ensure efficiency of emergency functions.',true,false,'{B2.4}'::text[]),('3ba33745-9140-539d-8fb6-ff995022ba52'::uuid,'Room Design',8,2,'The EOC and any multi-use space have the capability to display audio-visual media.',true,false,'{B3.6,B2.4}'::text[]),('75a26ad0-d869-500e-811f-d6fe5ec1433a'::uuid,'Room Design',8,3,'The EOC and any multi-use space have the capability to receive public,via intercom, announcements.',true,false,'{B2.4}'::text[]),('f7cbfa49-8e53-53dc-985c-e87128b5b7e3'::uuid,'Room Design',8,4,'The communication system within the EOC is located next to the operating room.',true,false,'{B2.4}'::text[]),('f5258013-8207-5cd7-9e67-ab9a161f39ff'::uuid,'Room Design',8,5,'The EOC has space, whether in one large room or a complex of rooms, for an operations area to perform emergency response and management functions;a communications room for centralized facsimiles, radios, and video teleconferencing (VTC); and to secure communications (e.g., secure voice, facsimile, and VTC).',true,false,'{B2.4}'::text[]),('2a3c2ff9-83b5-5e1a-a58e-e4a02dc2822f'::uuid,'Room Design',8,6,'The EOC has a dedicated communications room/center. This room/center is adequate to support EOC communications requirements.',true,false,'{B2.4}'::text[]),('2aa26994-faff-5668-b7cb-891b72d11499'::uuid,'Room Design',8,7,'The EOC has access to support areas(e.g., file room and server sites).',true,false,'{B2.4}'::text[]),('b1c6e55e-f9f3-50b9-a914-ab125d23e5cb'::uuid,'Room Design',8,8,'Once activated, the EOC has a dedicated operations room with adequate space to support the emergency response and EOC staff.',true,false,'{B2.4}'::text[]),('d0a541b6-6842-51be-af44-066613755b6c'::uuid,'Room Design',8,9,'The EOC has adequate facilities for food storage/preparation.',true,false,'{B2.4,B2.5}'::text[]),('528fa6b9-cb27-58c5-bd44-53b54f48787e'::uuid,'Room Design',8,10,'The EOC has an uninterruptible power supply (UPS) to critical systems. The duration of the UPS is adequate to support these systems/functions until the backup power comes on line.',true,false,'{B2.3}'::text[]),('9d921e35-fcbb-5d91-b07f-6a9a77d1f8ff'::uuid,'Room Design',8,11,'The EOC has a system to ensure backup power and emergency power generation.',true,false,'{B2.3}'::text[]),('09212bec-eb67-54b1-9d8c-11dc162b7670'::uuid,'Room Design',8,12,'The EOC has auxiliary lighting (e.g., flashlights, lanterns, batteries, and bulbs).',true,false,'{B2.3}'::text[]),('be769b5e-2680-56cf-92b2-d69836b011df'::uuid,'Room Design',8,13,'There is a dedicated auditorium-type/conference/media/break-out room/s in the general vicinity of the EOC. This room can be closed off to prevent an impact on operational activity.',true,false,'{B2.4}'::text[]),('34cc91db-59a4-569b-a689-27b6ab05e875'::uuid,'Personnel Space Requirements',9,1,'In accordance with the prescribed FEMA standards, the EOC allocates 150–200sq. ft. per person for the number of EOC staff assigned in an emergency.',true,false,'{B2.4}'::text[]),('5805156a-3df7-5087-9081-cb605a71d36f'::uuid,'Personnel Space Requirements',9,2,'Additional personnel space requirements are based upon maximum staffing levels for sustained operations (i.e., minimum – 72 hours: restrooms, meeting spaces, quiet rooms, executive office space, recreational room, fitness room, and smoking areas).',true,false,'{B2.4,B4.3}'::text[]),('2ba1f3c1-7189-582e-9ccd-2ff3446435cf'::uuid,'Personnel Space Requirements',9,3,'EOC design takes into account personnel space needs during sustained operations (i.e., minimum – 72 hours: showers and condensed bedding options).',true,false,'{B2.4,B2.5}'::text[]),('9a1db8d3-c578-54c5-880b-130ffc8d05c2'::uuid,'Personnel Space Requirements',9,4,'The EOC could provide sleeping accommodations to support sustained operations, if necessary (i.e., minimum – 72 hours).',true,false,'{B2.4,B2.5}'::text[]),('4d857fef-3e1c-56e2-a51a-d405440c17a8'::uuid,'Information Management Systems',10,1,'Local Area Networks (LAN) and State-Wide Area Networks (WAN) supporting emergency operations have adequate protection against cyber-attack (e.g., unauthorized access, denial of service, or malicious code).',true,false,'{B3.5}'::text[]),('3bf6cc0c-eaa5-50cf-a8e3-ec164b5a9f21'::uuid,'Information Management Systems',10,2,'Written procedures and guidelines exist for data/information handling.',true,false,'{B3.5}'::text[]),('07e3e63b-68db-5c00-842a-561d6889da6e'::uuid,'Information Management Systems',10,3,'Adequate processes and access-control procedures are in place to protect secure communications areas.',true,false,'{B3.5,B2.6}'::text[]),('5d02dbfb-586a-50ba-8cfc-6c6e014e928b'::uuid,'Information Management Systems',10,4,'Areas where classified or sensitive information is discussed can be isolated from unauthorized/un-cleared individuals.',true,false,'{B3.5}'::text[]),('6f4f9f9d-af90-59ac-9636-bd8c227dac6c'::uuid,'Information Management Systems',10,5,'The EOC has an uninterruptible power supply (UPS) to critical systems (e.g. servers). The duration of the UPS is adequate to support these systems/functions until the backup power comes on line.',true,false,'{B2.3}'::text[]),('5503159e-f88a-5df6-a2c6-e510c3e68399'::uuid,'Information Management Systems',10,6,'Radio communications are protected (i.e., encrypted or have privacy features).',true,false,'{B3.5}'::text[]),('6d06f8ec-8210-52bb-aa9a-d4bc281be1ff'::uuid,'Information Management Systems',10,7,'The EOC has a secure facsimile capability.',true,false,'{B3.5}'::text[]),('d53fd655-a9e6-5aaf-ad9a-d60caeccd9b3'::uuid,'Information Management Systems',10,8,'The EOC has a secure communications room with space adequate to support cleared EOC staff and secure communications requirements.',true,false,'{B3.5,B2.4}'::text[]),('473c8ff5-cb48-592c-8b93-c81d169f154b'::uuid,'Information Management Systems',10,9,'The EOC has secure communication capabilities and procedures with law enforcement and other consequence management agencies (e.g., WMD terrorism response).',true,false,'{B3.5,B3.4}'::text[]),('e7fd45be-b437-509b-be03-6663d07110ab'::uuid,'Information Management Systems',10,10,'The EOC has conducted a communications, electronics and information systems assessment to identify information security weaknesses. Corrective actions have been implemented.',true,false,'{B3.5,B7.6}'::text[]),('1b1defe5-bb4e-5279-b4a8-be3b726464b4'::uuid,'Information Management Systems',10,11,'Awareness training has ensured that EOC computer users understand the security risks associated with networked computers and practice good security.',true,false,'{B3.5,B7.2}'::text[]),('aa2dbf79-aba4-5cac-b0dd-f892c260ff45'::uuid,'Information Management Systems',10,12,'Clear and consistent information concerning information security policies and procedures are given to EOC staff.',true,false,'{B3.5}'::text[]),('f821805c-5a77-59f6-b939-577aa6349ca5'::uuid,'Information Management Systems',10,13,'EOC automation systems are protected by technical solutions such as firewalls and smartcards. Virus updates occur regularly.',true,false,'{B3.5}'::text[]),('404af737-6e4e-5023-b283-f6fe4be72282'::uuid,'Information Management Systems',10,14,'If personnel with security clearances are required, there are at least five with clearances who are trained to use secure equipment, control and protect classified material, and manage and control communications security.',true,false,'{B3.5,B4.2}'::text[]),('a9e89207-af0d-5372-8c54-14339fe044df'::uuid,'Information Management Systems',10,15,'The EOC has the capability to assimilate hazard information into a common format, such as a digital Geographic Information System (GIS), for comparative evaluation.',true,false,'{B5.3}'::text[]),('3c3c3791-e16c-5db0-92cb-bbbe1ad4a6ef'::uuid,'Standard Operating Procedures',11,1,'Emergency public informationprocedures',true,false,'{B7.1}'::text[]),('d2843c94-4050-57a1-a1c4-14f3915d1253'::uuid,'Standard Operating Procedures',11,2,'Activation, setup, and staffingprocedures',true,false,'{B1.3,B4.3}'::text[]),('a2163c47-b49a-51bb-9f1d-b35c45a82557'::uuid,'Standard Operating Procedures',11,3,'Security procedures',true,false,'{B2.6}'::text[]),('e5872f71-16e5-52e5-9dfa-efd328216dc8'::uuid,'Standard Operating Procedures',11,4,'Information handling procedures',true,false,'{B5.5,B3.5}'::text[]),('3b506843-b345-5a36-ba74-ddcda7fa703d'::uuid,'Standard Operating Procedures',11,5,'Communications procedures',true,false,'{B3.4}'::text[]),('5dc535be-177e-5d43-bdb3-0dfaa7587cfc'::uuid,'Standard Operating Procedures',11,6,'Action planning procedures',true,false,'{B6.5}'::text[]),('103f6b36-e986-57a3-91fe-5e43389ad87a'::uuid,'Standard Operating Procedures',11,7,'Resource management procedures',true,false,'{B6.2}'::text[]),('899d7d6c-6f4e-5c13-a695-aa1c16bfb23b'::uuid,'Standard Operating Procedures',11,8,'Coordination procedures (i.e., mutual aid agreements)',true,false,'{B6.6,B1.5}'::text[]),('2dcab324-e320-5a04-b08a-c2f11c33035d'::uuid,'Standard Operating Procedures',11,9,'Deactivation procedures',true,false,'{B1.3}'::text[]),('4c34ba8a-6163-5aff-9409-f5aece0cca0a'::uuid,'Standard Operating Procedures',11,10,'Procedures for relocating from the Primary EOC to the Alternate EOC',true,false,'{B2.7}'::text[]),('b48c4039-13c5-500a-8564-efd6283417b7'::uuid,'Standard Operating Procedures',11,11,'Procedures for after action reporting',true,false,'{B7.4}'::text[]),('c7fbd189-67f1-5930-9170-e8551458baf6'::uuid,'Communications',12,1,'The EOC has an alternate communication system.',true,false,'{B3.1}'::text[]),('ea89070f-fc14-56f2-8d14-54209d37904c'::uuid,'Communications',12,2,'The EOC has separate, dedicated facsimiles to transmit and receive documents.',true,false,'{B3.1}'::text[]),('c2ebafee-ff19-564a-af9b-860a003fceee'::uuid,'Communications',12,3,'Mobile or transportable telecommunication systems are identified, coordinated, and tested.',true,false,'{B3.1,B3.3}'::text[]),('af7a7130-972d-54e3-86c7-9d71fcc04378'::uuid,'Communications',12,4,'Alternate communication systems are identified for use in an emergency.',true,false,'{B3.1}'::text[]),('3f3339d3-fb5f-56cb-ad42-b1fffcea747a'::uuid,'Communications',12,5,'EOC has primary and alternate electrical capability to sustain the communication system.',true,false,'{B2.3,B3.3}'::text[]),('001848e7-b67e-5983-8988-be498bd0019e'::uuid,'Other Equipment',13,1,'The EOC has an adequate emergency power supply.',true,false,'{B2.3}'::text[]),('cb3ad849-6af7-55b4-af27-5b2d05af92eb'::uuid,'Other Equipment',13,2,'The EOC has an adequate supply of fuel for sustained operations (i.e., minimum—72 hours).',true,false,'{B2.3}'::text[]),('5ef2eaf9-afcb-566a-b6f6-406e66a63734'::uuid,'Other Equipment',13,3,'The EOC has adequate sanitary facilities.',true,false,'{B2.5}'::text[]),('5f733014-2998-545d-b02a-a70273a382c8'::uuid,'Other Equipment',13,4,'The EOC has adequate medical and sanitary supplies for sustained operations (i.e., minimum—72 hours).',true,false,'{B2.5}'::text[]),('60d552e9-1cf8-575b-a36a-92bb6282ad79'::uuid,'Other Equipment',13,5,'The number of available computers and any multi-use spaces is adequate to support emergency response operations.',true,false,'{B3.3}'::text[]),('09910a4e-675c-5244-8d2b-354d0c25ebf4'::uuid,'Other Equipment',13,6,'The number of servers is adequate to support emergency response operations.',true,false,'{B3.3}'::text[]),('a62c530e-2b93-511d-bc3a-129a7e9c38f0'::uuid,'Other Equipment',13,7,'The number of printers with toners, scanners, facsimile, and photocopiers is adequate to support emergency response operationsin the EOC.',true,false,'{B3.3}'::text[]),('eba87e1c-c106-5a84-955f-47bb12c91f5d'::uuid,'Other Equipment',13,8,'The EOC has auxiliary lighting (e.g., flashlights, lanterns, batteries, and bulbs).',true,false,'{B2.3}'::text[]),('c42f3cb8-7a77-58c7-8443-3b1456b29eb0'::uuid,'Other Equipment',13,9,'The EOC has sufficient administrative supplies for sustained operations (i.e., minimum—72 hours).',true,false,'{B2.5}'::text[]),('8a33cd0e-f432-53d0-a876-486d957c93c2'::uuid,'Other Equipment',13,10,'The EOC has paper and electronic copies with back-ups/stockpiles of all critical documentation and information such as reporting forms, tracking forms, rosters, and plans and procedures.',true,false,'{B5.5,B3.3}'::text[]),('0259be44-a60b-5d5b-8d88-e046f2992c03'::uuid,'Other Equipment',13,11,'Status and situation/incident boards permit immediate visual access to information by all EOC staff members.',true,false,'{B5.3,B3.6}'::text[]),('ebaf299c-0d03-5413-b16f-d950c7d31a26'::uuid,'Training',14,1,'Local government and Provincial EOCs conduct routine joint training exercises to practice, test, and refine common operations, reporting, and communications procedures.',true,false,'{B7.3,B1.5}'::text[]),('2a46ac70-8e0a-5822-b853-a7047c152edc'::uuid,'Training',14,2,'The EOC training program addresses EOC role in the Philippine DRRMSystem (e.g., ICS, and Clusters).',true,false,'{B7.2}'::text[]),('ea3561f4-3e9b-5107-94b6-379ad86919f9'::uuid,'Training',14,3,'The EOC training program addresses management staff training.',true,false,'{B7.2}'::text[]),('7e489b69-301c-572e-a969-aa8db6ae85e7'::uuid,'Training',14,4,'The EOC training program addresses elected officials training (e.g., EOC structure, operational methods, and priorities).',true,false,'{B7.2}'::text[]),('a49bab1d-8a8a-5a89-ad0c-3bcc262fa7e5'::uuid,'Training',14,5,'The EOC training program addresses positional roles and responsibilities.',true,false,'{B7.2,B4.5}'::text[]),('513eec62-aaec-5be9-a129-5c8d0b9cf138'::uuid,'Training',14,6,'The EOC training program addresses accredited volunteer training.',true,false,'{B7.2,B6.4}'::text[]),('b676dc8a-178c-5fd5-b74b-c871dec49718'::uuid,'Training',14,7,'Emergency management staff maintainsrecord/database of trained EOC personnel (e.g., training courses courses completed, evaluations, certifications, and expiration dates).',true,false,'{B7.2}'::text[]),('c8a21373-6916-5aed-ad08-cea77b001124'::uuid,'Training',14,8,'Personnel have received training in Rapid Damage and Needs Assessment (RDANA) procedures and other HADR/DRRM-related trainings consistent with national requirements.',true,false,'{B7.2}'::text[]),('99bf33e5-1eb9-5efb-ab2c-df80688a5608'::uuid,'Training',14,9,'Staff members are familiar with the provisions for requesting disaster assistance according to the emergency operations plan.',true,false,'{B7.2}'::text[]),('1fe84462-7480-5d15-b449-e3f2248ec3c1'::uuid,'Training',14,10,'Staff members are trained and qualified to fulfill responsibilities under local, Regional,National, and International policy guidelines and protocols.',true,false,'{B7.2}'::text[]),('9de9823d-a8d4-5e68-9e9b-eaad52aa5d40'::uuid,'Training',14,11,'EOC staff members are provided with adequatetraining opportunities for professional development to enhance their emergency management qualifications.',true,false,'{B7.2}'::text[]),('3654f6bc-eed9-57e0-bfcd-ab0703e64b77'::uuid,'Training',14,12,'Personnel are trained to use communications systems, including back-up and alternate systems.',true,false,'{B7.2,B3.1}'::text[]),('5a0c48ac-9c4d-5568-92eb-79b357ae24b1'::uuid,'Training',14,13,'Personnel are trained on specific procedures to limit the effects of hazards on the EOC, including maintaining functionality and protecting equipment from potential risks such as flooding or wind events.',true,false,'{B7.2}'::text[]),('b28a325b-0709-5ff3-a00f-38b0d9e5ad1d'::uuid,'Training',14,14,'Training materials are in place to quickly assimilate new and external personnel to the EOC including job descriptions, job aids, and specialized equipment training.',true,false,'{B4.5,B7.2}'::text[]),('08d7c431-2351-574d-a49d-bbf2b6b7b3e5'::uuid,'Training',14,15,'Personnel, both EOC personnel and outgoing day staff, are trained in the relocation process when establishing the Alternate EOC.',true,false,'{B7.2,B2.7}'::text[]),('084071ab-8a31-5934-ad8d-5e0772c74780'::uuid,'Exercises',15,1,'Regularly scheduled EOC exercises (e.g., activation and relocation, table top, and communications) are held. Participation by member agencies includes key personnel assigned to the EOC and is sufficient to ensure an efficient and timely activation during actual events.',true,false,'{B7.3}'::text[]),('8ee0c852-f1aa-534e-807a-deb966b3f99b'::uuid,'Exercises',15,2,'The EOC Operations Manual has been used in exercises, drills, or actual occurrences.',true,false,'{B7.3,B7.1}'::text[]),('bb1d6398-a77d-5106-a39e-92b7f4f1a35a'::uuid,'Exercises',15,3,'Impacts from natural or human-induced hazards to the EOC have been included in exercises or drills at all levels.',true,false,'{B7.3}'::text[]),('5626b002-1517-58af-90b6-0439dc8ab44c'::uuid,'Exercises',15,4,'Communication with all agencies, offices, organizations, and other stakeholdershas been incorporated into the exercises.',true,false,'{B7.3}'::text[]),('bd49a0a1-3d42-565e-a63e-e650e8e31313'::uuid,'Exercises',15,5,'All agencies, offices, organizations, and other stakeholder’s personnel have been included in drills and exercises in order to simulate an escalated EOC activation.',true,false,'{B7.3}'::text[]),('9ad705e9-1bd5-5a6b-bfd5-ccb33ba15032'::uuid,'Exercises',15,6,'Strict implementation of access control and security measures has been included in emergency exercises.',true,false,'{B7.3,B2.6}'::text[]),('9ae4c3df-4af3-53d8-8175-f083b5746017'::uuid,'Exercises',15,7,'The generator has been used in emergency drills, exercises, or actual occurrences.',true,false,'{B7.3,B2.3}'::text[]),('987674fd-1a8b-5f8c-8691-e65d45964b99'::uuid,'Exercises',15,8,'The relocation of non-essential day staff and non-EOC personnel has been tested in exercises or drills.',true,false,'{B7.3,B2.7}'::text[]),('ad4c9ac6-5788-51b0-a177-8a1e7934ead1'::uuid,'Exercises',15,9,'The EOC has a staff position identified to coordinate the development and implementation of emergency management exercises.',true,false,'{B7.3,B4.1}'::text[]),('0ea509c4-dca8-533b-912d-f678b1d73ea6'::uuid,'Exercises',15,10,'After-Activity Reviews and Reports from exercises and actual activations are used to improve EOC functionality.',true,false,'{B7.4}'::text[])
